#include <string>
#include <cmath>
#include <algorithm>

class Solution {
public:
    int maxManhattanDistance(std::string moves) {
        int x = 0, y = 0, best = 0;
        for (char m : moves) {
            if (m == 'N') y++;
            else if (m == 'S') y--;
            else if (m == 'E') x++;
            else if (m == 'W') x--;
            best = std::max(best, std::abs(x) + std::abs(y));
        }
        return best;
    }
};

class Solution {
    public int maxManhattanDistance(String moves) {
        int x = 0, y = 0, best = 0;
        for (char m : moves.toCharArray()) {
            if (m == 'N') y++;
            else if (m == 'S') y--;
            else if (m == 'E') x++;
            else if (m == 'W') x--;
            best = Math.max(best, Math.abs(x) + Math.abs(y));
        }
        return best;
    }
}

